#!/usr/bin/env node
// Fake Playwright CLI for e2e-rail's own tests (CommonJS on purpose: this package.json has no "type").
//   node cli.js test --list …        -> prints <cwd>/stub/list.json; with STUB_PW_LIST_PROJECT set, every listed test
//                                       gets that project too (a config that picks projects by env)
//   node cli.js test …               -> writes <cwd>/stub/report-*.json to the JSON output path, exits STUB_PW_RC; with
//                                       STUB_PW_FAIL_IF_LISTED=<text>, a run whose --test-list names <text> writes
//                                       report-fail.json and exits 1 (the code a selection runs decides the outcome)
//   node cli.js merge-reports … <d>  -> writes <d>/index.html
// Every stub JSON may contain <ABS_APP_DIR>; it is replaced by process.cwd() (the app dir).
const fs = require('node:fs');
const path = require('node:path');
const stub = path.join(process.cwd(), 'stub');
const argv = process.argv.slice(2);
const read = (file) => fs.readFileSync(file, 'utf8').replace(/<ABS_APP_DIR>/g, process.cwd());
if (process.env.STUB_PW_ARGV_FILE) fs.writeFileSync(process.env.STUB_PW_ARGV_FILE, JSON.stringify(argv));
if (argv[0] === 'merge-reports') {
  const dir = argv[argv.length - 1];
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, 'index.html'), '<html>merged</html>');
  process.exit(0);
}
if (argv.includes('--list')) {
  const list = JSON.parse(read(path.join(stub, 'list.json')));
  const extra = process.env.STUB_PW_LIST_PROJECT;
  const addTo = (suite) => {
    for (const spec of suite.specs || []) spec.tests.push({ projectName: extra, status: 'skipped', results: [] });
    for (const s of suite.suites || []) addTo(s);
  };
  if (extra) for (const s of list.suites) addTo(s);
  process.stdout.write(JSON.stringify(list));
  process.exit(0);
}
let src = process.env.STUB_PW_REPORT || path.join(stub, 'report-pass.json');
let rc = Number(process.env.STUB_PW_RC || 0);
const failIfListed = process.env.STUB_PW_FAIL_IF_LISTED;
const listAt = argv.indexOf('--test-list');
if (failIfListed && listAt >= 0 && fs.readFileSync(argv[listAt + 1], 'utf8').includes(failIfListed)) {
  src = path.join(stub, 'report-fail.json');
  rc = 1;
}
const out = process.env.PLAYWRIGHT_JSON_OUTPUT_FILE || process.env.PLAYWRIGHT_JSON_OUTPUT_NAME;
if (out) {
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, read(src));
}
process.exit(rc);
